/* Stable slots in a flat teaching diagram, not a 3D geometry calculation. */
const molBondLength=150;
function molAngles(element){if(element==='O'||element==='S')return[-142.25,-37.75];if(['N','P','B'].includes(element))return[-90,30,150];return[-90,0,90,180].slice(0,chemElements[element].bonds)}
function molLoneAngles(element){if(element==='O'||element==='S')return[45,135];if(element==='N'||element==='P')return[90];return[0,90,180].slice(0,(chemElements[element].valence-chemElements[element].bonds)/2)}
function molPoint(atom,slot,radius=molBondLength){const angle=molAngles(atom.element)[slot]*Math.PI/180;return{x:atom.x+radius*Math.cos(angle),y:atom.y+radius*Math.sin(angle)}}
function molFreeSlots(atoms,bonds,i){const used=new Set();bonds.forEach(b=>{if(b[0]===i)(b[3]||[]).forEach(k=>used.add(k));if(b[1]===i)(b[4]||[]).forEach(k=>used.add(k))});return molAngles(atoms[i].element).map((_,k)=>k).filter(k=>!used.has(k))}
function molSyncPorts(atoms,bonds){const used=atoms.map(()=>new Set());for(const b of bonds){for(let end=0;end<2;end++){const i=b[end],other=b[1-end],angles=molAngles(atoms[i].element),old=b[3+end]||[];const slots=old.slice(0,b[2]).filter(k=>Number.isInteger(k)&&k>=0&&k<angles.length&&!used[i].has(k));slots.forEach(k=>used[i].add(k));const direction=Math.atan2(atoms[other].y-atoms[i].y,atoms[other].x-atoms[i].x)*180/Math.PI;while(slots.length<b[2]){const choices=angles.map((a,k)=>({k,delta:Math.abs(((a-direction+540)%360)-180)})).filter(v=>!used[i].has(v.k)).sort((a,b)=>a.delta-b.delta);if(!choices.length)break;slots.push(choices[0].k);used[i].add(choices[0].k)}b[3+end]=slots}}}
function molClaimBond(atoms,bonds,a,b,slotA,slotB){molSyncPorts(atoms,bonds);const freeA=molFreeSlots(atoms,bonds,a),freeB=molFreeSlots(atoms,bonds,b);slotA=slotA??freeA[0];slotB=slotB??freeB[0];if(!freeA.includes(slotA)||!freeB.includes(slotB)||!chemCanBond(atoms,bonds,a,b))return false;const edge=bonds.find(v=>(v[0]===a&&v[1]===b)||(v[0]===b&&v[1]===a));if(edge){edge[2]++;edge[edge[0]===a?3:4].push(slotA);edge[edge[0]===b?3:4].push(slotB)}else bonds.push([a,b,1,[slotA],[slotB]]);if(atoms[b].element==='H'){molPlaceHydrogen(atoms,bonds,b,molPoint(atoms[a],slotA))}else if(atoms[a].element==='H'){molPlaceHydrogen(atoms,bonds,a,molPoint(atoms[b],slotB))}molKeepOnBoard(atoms);return true}
function molKeepOnBoard(atoms){if(!atoms.length)return;const dx=Math.max(0,80-Math.min(...atoms.map(a=>a.x))),dy=Math.max(0,80-Math.min(...atoms.map(a=>a.y)));if(dx||dy)atoms.forEach(a=>{a.x+=dx;a.y+=dy})}
function molComponent(bonds,start){const seen=new Set([start]);let change=true;while(change){change=false;for(const [a,b]of bonds){if(seen.has(a)&&!seen.has(b)){seen.add(b);change=true}if(seen.has(b)&&!seen.has(a)){seen.add(a);change=true}}}return [...seen]}
function molHydrideLayout(m){const heavy=m.atoms.map((a,i)=>a.element!=='H'?i:-1).filter(i=>i>=0);if(heavy.length!==1||m.bonds.length!==m.atoms.length-1)return null;const center=heavy[0],neighbors=m.bonds.map(([a,b,n])=>n===1?(a===center?b:b===center?a:-1):-1);if(neighbors.some(i=>i<0||m.atoms[i].element!=='H')||neighbors.length!==molAngles(m.atoms[center].element).length)return null;const atoms=m.atoms.map(a=>({...a}));atoms[center].x=230;atoms[center].y=230;neighbors.forEach((i,k)=>Object.assign(atoms[i],molPoint(atoms[center],k)));return atoms}
function molFindSnap(atoms,bonds,moving,point){if(atoms[moving].element!=='H'||bonds.some(b=>b[0]===moving||b[1]===moving))return null;let best=null;atoms.forEach((a,i)=>{if(i===moving||!chemCanBond(atoms,bonds,moving,i))return;for(const slot of molFreeSlots(atoms,bonds,i)){const port=molPoint(a,slot,49),destination=molPoint(a,slot),distance=Math.min(Math.hypot(point.x-port.x,point.y-port.y),Math.hypot(point.x-destination.x,point.y-destination.y));if(distance<=70&&(!best||distance<best.distance))best={atom:i,slot,distance,...destination}}});return best}

function molPlaceHydrogen(atoms,bonds,i,point){const previous={x:atoms[i].x,y:atoms[i].y};Object.assign(atoms[i],point);atoms.forEach((a,j)=>{if(j===i||bonds.some(b=>b[0]===j||b[1]===j)||Math.hypot(a.x-point.x,a.y-point.y)>=105)return;const clear=p=>!atoms.some((other,k)=>k!==j&&Math.hypot(other.x-p.x,other.y-p.y)<110);if(clear(previous)){Object.assign(a,previous);return}for(let k=0;k<1000;k++){const p={x:100+(k%5)*150,y:100+Math.floor(k/5)*150};if(clear(p)){Object.assign(a,p);break}}})}

// Repositioning changes only coordinates; bond order and occupied electron slots stay intact.
function molMoveTargets(bonds,index,mode='atom'){return mode==='molecule'?molComponent(bonds,index):[index]}
function molMoveAtoms(atoms,origin,indices,dx,dy){
 const shiftX=Math.max(dx,80-Math.min(...indices.map(i=>origin[i].x)));
 const shiftY=Math.max(dy,80-Math.min(...indices.map(i=>origin[i].y)));
 indices.forEach(i=>{atoms[i].x=origin[i].x+shiftX;atoms[i].y=origin[i].y+shiftY});
}
